import numpy as np
def _sb26_comps(a, colour):
    mask = (a == colour)
    seen = np.zeros(mask.shape, bool)
    out = []
    for y, x in zip(*np.where(mask)):
        if seen[y,x]: continue
        stack=[(y,x)]; seen[y,x]=True; comp=[]
        while stack:
            yy,xx=stack.pop(); comp.append((yy,xx))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=yy+dy,xx+dx
                if 0<=ny<64 and 0<=nx<64 and mask[ny,nx] and not seen[ny,nx]:
                    seen[ny,nx]=True; stack.append((ny,nx))
        out.append(comp)
    return out

def solve_sb26():
    g=grid(); start=levels()
    sources={}
    for c in np.unique(g):
        c=int(c)
        if c in (0,2,4,5,8): continue
        for comp in _sb26_comps(g,c):
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            if min(ys)>=54 and len(comp)>=8:
                sources[c]=(round(sum(xs)/len(xs)),round(sum(ys)/len(ys)))
    targets=[]
    for c in np.unique(g):
        c=int(c)
        if c in (0,2,4,5,8): continue
        for comp in _sb26_comps(g,c):
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            if max(ys)<11 and len(comp)>=8:
                targets.append((sum(xs)/len(xs),c))
    targets.sort()
    pads=[]
    for comp in _sb26_comps(g,2):
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        if 24<=min(ys) and max(ys)<=36 and len(comp)>=2:
            pads.append((round(sum(xs)/len(xs)),round(sum(ys)/len(ys))))
    pads.sort()
    for (_,c),dst in zip(targets,pads):
        if not alive() or levels()!=start: break
        click(*sources[c]); click(*dst)
    if alive() and levels()==start: press(5)
    return levels()>start
